from comfy_trials import *
import sys
master=upload(OUT/'v2-master.png')
style='One exquisite full-body adult princess knight, same character design as image1: blonde high ponytail, blue-jeweled gold tiara, silver armor with gold engraving, dark fitted underlayer, blue skirt and long embroidered blue cape, straight longsword. Detailed 2D game illustration. Image1 defines IDENTITY AND COSTUME ONLY, not pose. Animate the WHOLE BODY: head tilts and translates, ribcage rotates independently of pelvis, shoulders follow the action, hips shift over the supporting foot. Hair and cape lag behind with follow-through. Fixed camera looking from her left/front side toward her right-facing stance. Entire character and sword inside canvas with generous margins. Neutral flat pale gray background. No text, no multiple figures, no motion streaks. '
def saved(name):return upload(OUT/(name+'.png'))
stage=sys.argv[1] if len(sys.argv)>1 else 'keys'
if stage=='keys':
 q=get('/queue')
 if q['queue_running'] or q['queue_pending']:raise RuntimeError('ComfyUI busy')
 run('v3-attack-A',style+'ANTICIPATION for a powerful downward diagonal slash: her center of mass is visibly lowered, both knees bent, 70 percent of weight over the REAR LEFT foot. Pelvis shifts left, chest twists away from the strike and leans back, chin tucked, head slightly tilted downward toward the target on the right. Near hand draws the sword high behind her head toward the left, elbow bent. Other arm bent beside her ribs. This must be a dynamic coiled crouch, NOT upright standing.',master,size=(1024,1024))
 run('v3-attack-B',style+'Image2 is the immediately preceding windup. Draw the next MAIN STRIKE keyframe, continuing that action: push off rear left toes, transfer weight strongly to front right foot, pelvis moves RIGHT, front knee bends deeply and back leg extends. Chest rotates and leans FORWARD 25 degrees, shoulder leads the near arm into a forward downward sword slash. Head follows chest forward, chin down, eyes at target. Sword is extending toward the right in front of chest, halfway through a descending diagonal arc. Ponytail and cape trail toward the LEFT. Keep image2 costume details and camera, but substantially change whole-body pose.',master,saved('v3-attack-A'),size=(1024,1024))
 run('v3-attack-C',style+'Image2 is the preceding strike. Draw the next FOLLOW-THROUGH keyframe: center of mass settles lower onto front right leg, front knee bent, rear heel lifted. Pelvis and chest continue turning toward right; upper body leans forward, head follows chest and tilts down. Near hand finishes LOW in front of the right knee, sword points diagonally down right, tip entirely visible above ground. Free arm bent back as counterbalance. Hair and cape catch up and sweep slightly forward. Preserve costume and anatomy, continue image2 action. Clearly show that the entire body absorbed the strike.',master,saved('v3-attack-B'),size=(1024,1024))
elif stage=='inbetweens':
 for name,a,b,detail in [('v3-attack-AB','v3-attack-A','v3-attack-B','weight is transferring off rear foot, hips begin driving right, chest starts turning, blade is high above forehead on descending arc'),('v3-attack-BC','v3-attack-B','v3-attack-C','weight settles over front leg, shoulders continue rotating, blade passes waist height downward')]:
  run(name,style+'Image2 is the earlier keyframe; image3 is the later keyframe. Draw ONE NEW intermediate animation frame halfway between these two poses. Follow the same limb identities, costume, camera and sword grip. Interpolate head position, chest lean, pelvic shift, shoulder rotation, knees and sword angle together, not just arms and legs. Do not copy either endpoint. Specific phase: '+detail+'.',master,saved(a),size=(1024,1024),end=saved(b))
elif stage=='walk':
 run('v3-walk-A',style+'Walking to the RIGHT, first contact keyframe: near left leg extends forward right heel down, far right leg extends back left toe down. Pelvis is lowered and translated over the forward leg; torso leans gently forward and counter-rotates against hips. Head rides above chest with chin slightly down. Sword hangs low by near hip without freezing shoulder movement. Hair and cape trail left. Clearly separated two legs and two feet.',master,size=(1024,1024))
 run('v3-walk-B',style+'Image2 is first contact of the walking cycle. Draw OPPOSITE contact half a stride later: near LEFT LEG now extends BACK LEFT, far RIGHT LEG extends FORWARD RIGHT. Exchange which leg leads. Pelvis rotates oppositely, ribcage counter-rotates the other way, head follows with slight tilt. Same person continues walking right, two legs only. Keep same camera, costume, sword grip and ground plane; allow all body parts to move.',master,saved('v3-walk-A'),size=(1024,1024))
 for name,a,b in [('v3-walk-AB','v3-walk-A','v3-walk-B'),('v3-walk-BA','v3-walk-B','v3-walk-A')]:
  run(name,style+'Image2 is the earlier walking contact and image3 is the next opposite contact. Create ONE intervening passing/up pose: support leg under pelvis nearly straight, other knee bends forward and foot clears ground. Pelvis and head rise visibly above contact poses, chest stays balanced over support leg, shoulders and hips counter-rotate. Exactly TWO legs. Do not combine endpoint legs. Preserve same costume and camera. This frame bridges the two reference poses.',master,saved(a),size=(1024,1024),end=saved(b))
